41	class WorksPageDomRuntime {
42	  private readonly _root: ParentNode;
43	
44	  constructor(root: ParentNode) {
45	    this._root = root;
46	  }
47	
48	  resolve(): WorksPageElements {
49	    return {
50	      root: this._queryElement<HTMLElement>(WORK_PAGE_DOM.rootSelector),
51	      canvas: this._queryCanvasElement(WORK_CANVAS_CONFIG.canvasId),
52	      grid: this._queryElement<HTMLElement>(WORK_PAGE_DOM.gridSelector),
53	      gridList: this._queryElement<HTMLUListElement>(
54	        WORK_PAGE_DOM.gridListSelector,
55	      ),
56	      gridPagination: this._queryElement<HTMLElement>(
57	        WORK_PAGE_DOM.gridPaginationSelector,
58	      ),
59	      controls: this._queryElement<HTMLElement>(WORK_PAGE_DOM.controlsSelector),
60	      toggle: this._queryElement<HTMLElement>(WORK_PAGE_DOM.toggleSelector),
61	      filterWrap: this._queryElement<HTMLElement>(
62	        WORK_PAGE_DOM.filterWrapSelector,
63	      ),
64	      filterButton: this._queryElement<HTMLButtonElement>(
65	        WORK_PAGE_DOM.filterButtonSelector,
66	      ),
67	      filterPanel: this._queryElement<HTMLElement>(
68	        WORK_PAGE_DOM.filterPanelSelector,
69	      ),
70	      dragHint: this._queryElement<HTMLElement>(WORK_PAGE_DOM.dragHintSelector),
71	    };
72	  }
73	
74	  readState(elements: WorksPageElements): WorksPageState {
75	    const root = elements.root;
76	    const viewRaw = root?.dataset.view;
77	    const view: WorksViewMode =
78	      viewRaw === "grid" || viewRaw === "scatter"
79	        ? viewRaw
80	        : WORK_PAGE_STATE_DEFAULT.view;
81	    const categoryRaw = root?.dataset.category?.trim() ?? "";
82	    const pageRaw = Number.parseInt(root?.dataset.page ?? "", 10);
83	    const limitRaw = Number.parseInt(root?.dataset.limit ?? "", 10);
84	
85	    return {
86	      view,
87	      category: categoryRaw.length > 0 ? categoryRaw : null,
88	      page:
89	        Number.isFinite(pageRaw) && pageRaw > 0
90	          ? pageRaw
91	          : WORK_PAGE_STATE_DEFAULT.page,
92	      limit:
93	        Number.isFinite(limitRaw) && limitRaw > 0
94	          ? limitRaw
95	          : WORK_PAGE_STATE_DEFAULT.limit,
96	    };
97	  }
98	
99	  private _queryElement<TElement extends HTMLElement>(
100	    selector: string,
101	  ): TElement | null {
102	    return this._root.querySelector<TElement>(selector);
103	  }
104	
105	  private _queryCanvasElement(canvasId: string): HTMLCanvasElement | null {
106	    return this._root.querySelector<HTMLCanvasElement>(`#${canvasId}`);
107	  }
108	}
