153	class WorksPageUiRuntime {
154	  private readonly _elements: WorksPageElements;
155	  private _gridEnterRafId: number | null = null;
156	  private _toggleRevealRafId: number | null = null;
157	  private _toggleRevealTimeoutId: number | null = null;
158	  private _dragHintTimeoutId: number | null = null;
159	  private _dragHintDeactivateTimeoutId: number | null = null;
160	  private _dragHintExitTimeoutId: number | null = null;
161	
162	  constructor(elements: WorksPageElements) {
