182	    this.hideIntroIfReady();
183	    this.showGrid();
184	    this.showViewToggle();
185	    const grid = this._elements.grid;
186	    if (!grid) return;
187	    grid.classList.remove(WORK_PAGE_DOM.gridEnterClass);
