199	    if (this._toggleRevealRafId !== null) {
200	      FrameScheduler.cancel(this._toggleRevealRafId);
201	      this._toggleRevealRafId = null;
202	    }
203	    this._toggleRevealTimeoutId = window.setTimeout(
204	      () => {
205	        this._toggleRevealTimeoutId = null;
206	        this._toggleRevealRafId = FrameScheduler.request(() => {
207	          this.showViewToggle();
208	          this._toggleRevealRafId = null;
