214	
215	  showViewToggle(): void {
216	    const controls = this._elements.controls;
217	    if (!controls) return;
218	    this._elements.root?.setAttribute("data-ui-ready", "true");
219	    controls.hidden = false;
220	    controls.dataset.ready = "true";
221	    controls.removeAttribute("inert");
222	    Aria.setHidden(controls, false);
