224	
225	  hideViewToggle(): void {
226	    const controls = this._elements.controls;
227	    if (!controls) return;
228	    this._elements.root?.setAttribute("data-ui-ready", "false");
229	    controls.hidden = true;
230	    controls.dataset.ready = "false";
231	    controls.setAttribute("inert", "");
