266	
267	  syncFilterSelection(
268	    category: string | null,
269	    options?: { animateLabel?: boolean },
270	  ): void {
271	    const filterButton = this._elements.filterButton;
272	    const filterPanel = this._elements.filterPanel;
273	    if (!filterButton || !filterPanel) return;
274	    const optionNodes = filterPanel.querySelectorAll<HTMLElement>(
275	      WORK_PAGE_DOM.filterOptionSelector,
276	    );
277	    let activeLabel = "전체";
278	    optionNodes.forEach((option) => {
279	      const optionCategory = option.dataset.category?.trim() ?? "";
280	      const isActive =
281	        (category === null && optionCategory.length === 0) ||
282	        optionCategory === (category ?? "");
283	      option.classList.toggle("is-active", isActive);
284	      option.setAttribute("aria-pressed", isActive ? "true" : "false");
285	      if (!isActive) return;
286	      activeLabel =
287	        option.dataset.label?.trim() || option.textContent?.trim() || "전체";
288	    });
289	    const labelElement = filterButton.querySelector<HTMLElement>(
290	      ".no-works-canvas__filter-button-label",
291	    );
292	    if (!labelElement) return;
293	    const previousLabel = labelElement.textContent ?? "";
294	    const shouldAnimate =
295	      options?.animateLabel === true && previousLabel !== activeLabel;
296	
297	    if (!shouldAnimate) {
298	      labelElement.textContent = activeLabel;
299	      return;
300	    }
301	
302	    filterButton.classList.remove("is-filter-label-entering");
303	    filterButton.classList.add("is-filter-label-leaving");
304	    window.setTimeout(() => {
305	      labelElement.textContent = activeLabel;
306	      filterButton.classList.remove("is-filter-label-leaving");
307	      filterButton.classList.add("is-filter-label-entering");
308	      window.setTimeout(() => {
309	        filterButton.classList.remove("is-filter-label-entering");
310	      }, WORKS_FILTER_TRANSITION_MS);
311	    }, WORKS_FILTER_TRANSITION_MS);
312	  }
313	
314	  syncViewLinks(category: string | null): void {
315	    const toggle = this._elements.toggle;
316	    if (!toggle) return;
317	    const links = toggle.querySelectorAll<HTMLAnchorElement>("a[href]");
318	    links.forEach((link) => {
319	      const url = new URL(link.href, window.location.origin);
320	      const view = url.searchParams.get("view") ?? "scatter";
321	      url.searchParams.set("view", view);
322	      if (category) {
323	        url.searchParams.set("category", category);
324	      } else {
325	        url.searchParams.delete("category");
326	      }
327	      link.href = `${url.pathname}${url.search}${url.hash}`;
328	    });
329	  }
330	
331	  showDragHint(): void {
332	    if (!WORK_HINT_CONFIG.enabled) return;
333	    this._clearDragHintTimers();
334	    const dragHint = this._elements.dragHint;
335	    if (!dragHint) return;
336	    dragHint.hidden = false;
337	    dragHint.classList.remove(WORK_PAGE_DOM.dragHintHidingClass);
338	    dragHint.classList.add(WORK_PAGE_DOM.dragHintVisibleClass);
339	    dragHint.removeAttribute("inert");
340	    Aria.setHidden(dragHint, false);
341	    this._dragHintTimeoutId = window.setTimeout(() => {
342	      this.hideDragHint();
343	    }, WORK_HINT_CONFIG.autoHideMs);
