351	
352	  hideDragHint(): void {
353	    this._clearDragHintTimers();
354	    const dragHint = this._elements.dragHint;
355	    if (!dragHint) return;
356	    dragHint.hidden = false;
357	    this._dragHintDeactivateTimeoutId = window.setTimeout(() => {
358	      dragHint.classList.remove(WORK_PAGE_DOM.dragHintVisibleClass);
359	      dragHint.classList.add(WORK_PAGE_DOM.dragHintHidingClass);
360	      this._dragHintDeactivateTimeoutId = null;
361	      this._dragHintExitTimeoutId = window.setTimeout(() => {
362	        dragHint.setAttribute("inert", "");
363	        Aria.setHidden(dragHint, true);
364	        dragHint.classList.remove(WORK_PAGE_DOM.dragHintHidingClass);
365	        this._dragHintExitTimeoutId = null;
366	      }, WORK_HINT_CONFIG.exitDurationMs);
367	    }, WORK_HINT_CONFIG.hideStartDelayMs);
368	  }
369	
370	  dispose(): void {
371	    if (this._gridEnterRafId !== null) {
372	      FrameScheduler.cancel(this._gridEnterRafId);
373	      this._gridEnterRafId = null;
374	    }
375	    if (this._toggleRevealRafId !== null) {
376	      FrameScheduler.cancel(this._toggleRevealRafId);
377	      this._toggleRevealRafId = null;
378	    }
379	    if (this._toggleRevealTimeoutId !== null) {
380	      window.clearTimeout(this._toggleRevealTimeoutId);
381	      this._toggleRevealTimeoutId = null;
382	    }
383	    this._clearDragHintTimers();
384	    this._resetDragHint();
385	    this._elements.grid?.classList.remove(WORK_PAGE_DOM.gridEnterClass);
386	  }
387	
388	  private _syncViewAttributes(view: WorksViewMode): void {
389	    this._elements.root?.setAttribute("data-view", view);
390	    this._elements.toggle?.setAttribute("data-view", view);
391	  }
392	
393	  private _clearDragHintTimers(): void {
394	    if (this._dragHintTimeoutId !== null) {
395	      window.clearTimeout(this._dragHintTimeoutId);
396	      this._dragHintTimeoutId = null;
397	    }
398	    if (this._dragHintExitTimeoutId !== null) {
399	      window.clearTimeout(this._dragHintExitTimeoutId);
400	      this._dragHintExitTimeoutId = null;
401	    }
402	    if (this._dragHintDeactivateTimeoutId !== null) {
403	      window.clearTimeout(this._dragHintDeactivateTimeoutId);
404	      this._dragHintDeactivateTimeoutId = null;
405	    }
406	  }
407	
408	  private _resetDragHint(): void {
409	    const dragHint = this._elements.dragHint;
410	    if (!dragHint) return;
411	    dragHint.hidden = true;
412	    dragHint.setAttribute("inert", "");
413	    dragHint.classList.remove(
414	      WORK_PAGE_DOM.dragHintVisibleClass,
415	      WORK_PAGE_DOM.dragHintHidingClass,
416	    );
417	    Aria.setHidden(dragHint, true);
418	  }
419	}
