421	class WorksGridFeedRuntime {
422	  private readonly _state: WorksPageState;
423	  private readonly _elements: WorksPageElements;
424	  private _feedState: WorksGridFeedState = {
425	    nextOffset: null,
426	    hasMore: false,
427	  };
428	  private _abortController: AbortController | null = null;
429	  private _loading = false;
430	  private _thresholdArmed = true;
431	  private _bound = false;
432	
433	  constructor(state: WorksPageState, elements: WorksPageElements) {
434	    this._state = state;
435	    this._elements = elements;
436	  }
437	
438	  async init(): Promise<void> {
439	    const list = this._elements.gridList;
440	    if (!list) return;
441	    this._clearList();
442	    this._feedState = {
443	      nextOffset: null,
444	      hasMore: false,
445	    };
446	    this._syncRootState();
447	    this._abortController?.abort();
448	    this._abortController = new AbortController();
449	    try {
450	      const response = await this._fetchItems(this._resolveInitialOffset());
451	      this._appendItems(response.items);
452	      this._feedState = {
453	        nextOffset: response.nextOffset,
454	        hasMore: response.hasMore,
455	      };
456	      this._syncRootState();
457	      this._syncPaginationVisibility();
458	    } catch (error) {
459	      if (error instanceof DOMException && error.name === "AbortError") return;
460	      throw error;
461	    } finally {
462	      this._abortController = null;
463	    }
464	  }
465	
466	  bind(): void {
467	    if (this._bound) return;
468	    window.addEventListener("scroll", this._handleScroll, { passive: true });
469	    this._bound = true;
470	  }
471	
472	  dispose(): void {
473	    if (this._bound) {
474	      window.removeEventListener("scroll", this._handleScroll);
475	      this._bound = false;
476	    }
477	    this._abortController?.abort();
478	    this._abortController = null;
479	    this._loading = false;
480	    this._thresholdArmed = true;
481	  }
482	
483	  private readonly _handleScroll = (): void => {
484	    if (!this._feedState.hasMore) return;
485	    if (this._loading) return;
486	    const list = this._elements.gridList;
487	    if (!list) return;
488	    const thresholdReached = this._isThresholdReached(list);
489	    if (!thresholdReached) {
490	      this._thresholdArmed = true;
491	      return;
492	    }
493	    if (!this._thresholdArmed) return;
494	    this._thresholdArmed = false;
495	    void this._loadMore();
496	  };
497	
498	  private _isThresholdReached(list: HTMLElement): boolean {
499	    const rect = list.getBoundingClientRect();
500	    return (
501	      rect.bottom - window.innerHeight <= WORK_GRID_INFINITE_CONFIG.thresholdPx
502	    );
503	  }
504	
505	  private async _loadMore(): Promise<void> {
506	    if (!this._feedState.hasMore) return;
507	    if (this._feedState.nextOffset === null) return;
508	    if (this._loading) return;
509	    this._loading = true;
510	    this._abortController?.abort();
511	    this._abortController = new AbortController();
512	    try {
513	      const response = await this._fetchItems(this._feedState.nextOffset);
514	      this._appendItems(response.items);
515	      this._feedState = {
516	        nextOffset: response.nextOffset,
517	        hasMore: response.hasMore,
518	      };
519	      this._syncRootState();
520	      this._syncPaginationVisibility();
521	    } catch (error) {
522	      if (error instanceof DOMException && error.name === "AbortError") return;
523	      console.warn(
524	        "[WorksGridFeedRuntime.loadMore] Grid feed request failed.",
525	        error,
526	      );
527	      this._thresholdArmed = true;
528	    } finally {
529	      this._loading = false;
530	      this._abortController = null;
531	    }
532	  }
533	
534	  private async _fetchItems(offset: number) {
535	    return fetchWorksList(
536	      offset,
537	      this._state.limit,
538	      this._state.category,
539	      this._abortController?.signal,
540	    );
541	  }
542	
543	  private _resolveInitialOffset(): number {
544	    return Math.max(0, (this._state.page - 1) * this._state.limit);
545	  }
546	
547	  private _clearList(): void {
548	    this._elements.gridList?.replaceChildren();
549	  }
550	
551	  private _appendItems(items: ReadonlyArray<WorkApiItem>): void {
552	    if (items.length === 0) return;
553	    const list = this._elements.gridList;
554	    if (!list) return;
555	    const fragment = document.createDocumentFragment();
556	    items.forEach((item) => {
557	      fragment.append(this._createListItem(item));
558	    });
559	    list.append(fragment);
560	  }
561	
562	  private _createListItem(item: WorkApiItem): HTMLLIElement {
563	    const listItem = document.createElement("li");
564	    listItem.className = "no-sub-works__gallery-item";
565	    listItem.dataset.workNo = item.no;
566	
567	    const link = document.createElement("a");
568	    link.className = "no-sub-works__gallery-item__link";
569	    link.href = this._buildDetailHref(item.detailPath || "/works");
570	
571	    const imageWrap = document.createElement("div");
572	    imageWrap.className = "no-sub-works__gallery-item__img-wrap";
573	
574	    const imageInner = document.createElement("div");
575	    imageInner.className = "no-sub-works__gallery-item__img-inner";
576	
577	    const figure = document.createElement("figure");
578	    figure.className = "no-sub-works__gallery-item__img";
579	
580	    const media = this._createMedia(item);
581	    if (media) {
582	      figure.append(media);
583	    }
584	
585	    imageInner.append(figure);
586	    imageWrap.append(this._createGalleryItemCorner(), imageInner);
587	
588	    const body = document.createElement("div");
589	    body.className = "no-sub-works__gallery-item__body";
590	
591	    const title = document.createElement("h2");
592	    title.className = "no-sub-works__gallery-item__title";
593	    title.textContent = item.title ?? "";
594	    body.append(title);
595	
596	    link.append(imageWrap, body);
597	    listItem.append(link, this._createModalButton(item));
598	    return listItem;
599	  }
600	
601	  private _createMedia(
602	    item: WorkApiItem,
603	  ): HTMLVideoElement | HTMLImageElement | null {
604	    if (item.thumbnailImage) {
605	      const image = document.createElement("img");
606	      image.src = item.thumbnailImage;
607	      image.alt = item.title ?? "";
608	      return image;
609	    }
610	    if (item.thumbnailVideo) {
611	      const video = document.createElement("video");
612	      video.src = item.thumbnailVideo;
613	      video.autoplay = true;
614	      video.muted = true;
615	      video.loop = true;
616	      video.playsInline = true;
617	      return video;
618	    }
619	    return null;
620	  }
621	
622	  private _createModalButton(item: WorkApiItem): HTMLButtonElement {
623	    const button = document.createElement("button");
624	    button.type = "button";
625	    button.className =
626	      "no-corner-btn no-works-canvas__grid-link js-work-modal-trigger";
627	    button.setAttribute("aria-label", `${item.title || "Work"} modal view`);
628	    button.append(this._createModalButtonCorner());
629	    const text = document.createElement("span");
630	    text.className = "no-corner-btn__text";
631	    text.textContent = "View Modal";
632	    button.append(text, this._createModalButtonIcon());
633	    return button;
634	  }
635	
636	  private _createModalButtonCorner(): HTMLSpanElement {
637	    const root = document.createElement("span");
638	    root.className =
639	      "no-corner-bracket no-corner-btn__corner no-corner-bracket--shine";
640	    root.setAttribute("aria-hidden", "true");
641	
642	    const cornerSpecs = [
