756	  private _overlay: HTMLDivElement | null = null;
757	  private _locked = false;
758	  private _releaseScrollLock: (() => void) | null = null;
759	
760	  lock(): void {
761	    if (this._locked) return;
762	    this._locked = true;
763	    this._releaseScrollLock?.();
764	    this._releaseScrollLock = ScrollLock.lock({ pauseLenis: true });
765	    const overlay = document.createElement("div");
766	    overlay.setAttribute("aria-hidden", "true");
767	    overlay.style.position = "fixed";
768	    overlay.style.inset = "0";
769	    overlay.style.zIndex = "99999";
770	    overlay.style.pointerEvents = "auto";
771	    overlay.style.touchAction = "none";
772	    overlay.style.background = "transparent";
773	    overlay.style.cursor = "wait";
774	    document.body.appendChild(overlay);
775	    this._overlay = overlay;
776	  }
