778	  unlock(): void {
779	    if (!this._locked) return;
780	    this._locked = false;
781	    this._overlay?.remove();
782	    this._overlay = null;
783	    this._releaseScrollLock?.();
784	    this._releaseScrollLock = null;
785	  }
