1003	  private async _playScatterIntro(
1004	    runRevision: number,
1005	  ): Promise<SceneFromState | null> {
1006	    if (!WORK_INTRO_CONFIG.enabled) return null;
1007	    if (this.state.view !== "scatter") return null;
1008	    if (!(this.elements.canvas instanceof HTMLCanvasElement)) return null;
1009	
1010	    this._interactionLock.lock();
1011	    this.introRuntime?.dispose();
1012	    const introRuntime = new WorksIntroPlaybackRuntime();
1013	    this.introRuntime = introRuntime;
1014	
1015	    try {
1016	      const introState = await introRuntime.run(
1017	        WORK_CANVAS_CONFIG.canvasId,
1018	        this.elements.canvas,
1019	      );
1020	      if (!this._isActiveRun(runRevision)) return null;
1021	      return introState;
1022	    } catch (error) {
1023	      console.warn(
1024	        "[WorksPageRuntime._playScatterIntro] Intro playback failed.",
1025	        error,
1026	      );
1027	      return null;
1028	    } finally {
1029	      if (this.introRuntime === introRuntime) {
1030	        introRuntime.dispose();
1031	        this.introRuntime = null;
1032	      }
1033	      this._interactionLock.unlock();
1034	    }
1035	  }
