1143	
1144	    let closeAriaTimer: number | null = null;
1145	    const clearCloseAriaTimer = (): void => {
1146	      if (closeAriaTimer === null) return;
1147	      window.clearTimeout(closeAriaTimer);
1148	      closeAriaTimer = null;
1149	    };
1150	
1151	    const closePanel = (): void => {
1152	      clearCloseAriaTimer();
1153	      filterButton.setAttribute("aria-expanded", "false");
1154	      filterPanel.classList.remove("is-open");
1155	      // 패널 닫힘 트랜지션 후: 포커스 정리 + aria-hidden (WORKS_FILTER_TRANSITION_MS와 동기)
1156	      closeAriaTimer = window.setTimeout(() => {
1157	        closeAriaTimer = null;
1158	        const ae = document.activeElement;
1159	        if (ae instanceof Node && filterPanel.contains(ae)) {
1160	          filterButton.focus({ preventScroll: true });
1161	        }
1162	        filterPanel.setAttribute("aria-hidden", "true");
1163	      }, WORKS_FILTER_TRANSITION_MS);
1164	    };
1165	
1166	    const openPanel = (): void => {
1167	      clearCloseAriaTimer();
1168	      filterPanel.setAttribute("aria-hidden", "false");
1169	      filterPanel.classList.add("is-open");
1170	      filterButton.setAttribute("aria-expanded", "true");
1171	    };
1172	
1173	    const togglePanel = (): void => {
1174	      if (filterPanel.classList.contains("is-open")) {
1175	        closePanel();
1176	      } else {
1177	        openPanel();
1178	      }
1179	    };
1180	
1181	    const onFilterButtonClick = (event: MouseEvent): void => {
1182	      event.stopPropagation();
1183	      togglePanel();
1184	    };
1185	    filterButton.addEventListener("click", onFilterButtonClick);
1186	    this._scatterFilterCleanup.push(() =>
1187	      filterButton.removeEventListener("click", onFilterButtonClick),
1188	    );
1189	
1190	    const onPanelClick = (event: MouseEvent): void => {
1191	      const target = event.target as HTMLElement | null;
1192	      const option = target?.closest<HTMLElement>("[data-works-filter-option]");
1193	      if (!option) return;
1194	      const raw = option.dataset.category?.trim() ?? "";
1195	      const category = raw === "" ? null : raw;
1196	      this.state = { ...this.state, category };
1197	      this.elements.root?.setAttribute(
1198	        "data-category",
1199	        category === null ? "" : category,
1200	      );
1201	      scene.applyCategory(category);
1202	      this.uiRuntime?.syncFilterSelection(category, { animateLabel: true });
1203	      this.uiRuntime?.syncViewLinks(category);
1204	      this._syncScatterUrl(category);
1205	      closePanel();
1206	    };
1207	    filterPanel.addEventListener("click", onPanelClick);
1208	    this._scatterFilterCleanup.push(() =>
1209	      filterPanel.removeEventListener("click", onPanelClick),
1210	    );
1211	
1212	    const onDocumentClick = (event: MouseEvent): void => {
1213	      if (!wrap.contains(event.target as Node)) {
1214	        closePanel();
1215	      }
1216	    };
1217	    document.addEventListener("click", onDocumentClick);
1218	    this._scatterFilterCleanup.push(() =>
1219	      document.removeEventListener("click", onDocumentClick),
1220	    );
1221	
1222	    const onKeyDown = (event: KeyboardEvent): void => {
1223	      if (event.key !== "Escape") return;
