1239	  private _syncScatterUrl(category: string | null): void {
1240	    const url = new URL(window.location.href);
1241	    url.searchParams.set("view", "scatter");
1242	    if (category) {
1243	      url.searchParams.set("category", category);
1244	    } else {
1245	      url.searchParams.delete("category");
1246	    }
1247	    if (this.state.page > 1) {
