92	export function createWorkProjectItem(
93	  item: WorkApiItem,
94	  index: number,
95	): WorkProjectItem {
96	  const preset =
97	    WORK_PROJECT_VISUALS[item.category] ?? WORK_PROJECT_VISUALS.default;
98	  const useLandscape = preset.w > preset.h || index % 7 === 0;
99	  return {
100	    ...item,
101	    bg: preset.bg,
102	    ac: preset.ac,
103	    w: useLandscape ? 6.8 : preset.w,
104	    h: useLandscape ? 4.4 : preset.h,
105	  };
106	}
107	
108	export function formatWorkCategoryLabel(category: string): string {
109	  if (category.length === 0) return "";
110	  return WORK_CATEGORY_LABELS[category] ?? category;
111	}
